  const set = (id, v) => { $(id).value = v; $(id).dispatchEvent(new Event("input")); };
  snap("default 60kg 166cm");
  set("wt", 103.5); snap("103.5kg 166cm");
  set("wt", 82); snap("82kg");
  set("wt", 140); snap("140kg");
  document.querySelector('[data-late="skip"]').click(); snap("140kg skip");
